INNER JOIN [sys].[columns] [c] ON [d].[parent_column_id] = [c].[column_id] AND [d].[parent_object_id] = [c].[object_id]
WHERE ([d].[parent_object_id] = OBJECT_ID(N'[BrainSlotInvocations]') AND [c].[name] = N'StartedAtUtc');
IF @var67 IS NOT NULL EXEC(N'ALTER TABLE [BrainSlotInvocations] DROP CONSTRAINT ' + @var67 + ';');
ALTER TABLE [BrainSlotInvocations] ALTER COLUMN [StartedAtUtc] datetime2 NOT NULL;
CREATE INDEX [IX_BrainSlotInvocations_WorkspaceId_SlotId_StartedAtUtc] ON [BrainSlotInvocations] ([WorkspaceId], [SlotId], [StartedAtUtc]);
